      'lab-07': { title: 'Den Agenten auf Unternehmenswissen stützen', summary: 'Freigegebenes Wissen hinzufügen, mit dem Ausgangsstand vergleichen und Antwortgrenzen testen.', artifacts: ['Wissenskonfiguration', 'Grenzfalltests'], concepts: ['Wissen', 'Quellenbindung'], checklist: ['Lies die Lab-Beschreibung: Den Agenten auf Unternehmenswissen stützen', 'Führe den Konfigurations- oder Entwurfsschritt durch', 'Prüfe Erfolgsfälle und Grenzfälle', 'Speichere das benannte Artefakt oder den Prüfstand'] },
      'lab-08': { title: 'Azure AI Search konfigurieren und den Informationsabruf validieren', summary: 'Exakte, umformulierte, mehrdeutige, leere und veraltete Abrufszenarien testen.', artifacts: ['Abrufmatrix', 'Belegnotizen'], concepts: ['Azure AI Search', 'RAG'], checklist: ['Lies die Lab-Beschreibung: Azure AI Search konfigurieren und den Informationsabruf validieren', 'Führe den Konfigurations- oder Entwurfsschritt durch', 'Prüfe Erfolgsfälle und Grenzfälle', 'Speichere das benannte Artefakt oder den Prüfstand'] },
      'lab-09': { title: 'Ein Ticket-REST-API-Werkzeug aus OpenAPI hinzufügen', summary: 'Einen API-Vertrag importieren, Authentifizierung konfigurieren und Abfragen von Änderungen unterscheiden.', artifacts: ['OpenAPI-Werkzeug', 'API-Testprotokoll'], concepts: ['REST', 'OpenAPI'], checklist: ['Lies die Lab-Beschreibung: Ein Ticket-REST-API-Werkzeug aus OpenAPI hinzufügen', 'Führe den Konfigurations- oder Entwurfsschritt durch', 'Prüfe Erfolgsfälle und Grenzfälle', 'Speichere das benannte Artefakt oder den Prüfstand'] },
