      'lab-11': { title: 'Spezialisten aus Copilot Studio, Foundry und Fabric verbinden', summary: 'Routing-Metadaten definieren und spezialisierte Agenten mit klaren Zuständigkeitsgrenzen verbinden.', artifacts: ['Routing-Tests', 'Aktualisiertes ADR'], concepts: ['Verbundene Agenten', 'Foundry', 'Fabric'], checklist: ['Lies die Lab-Beschreibung: Spezialisten aus Copilot Studio, Foundry und Fabric verbinden', 'Führe den Konfigurations- oder Entwurfsschritt durch', 'Prüfe Erfolgsfälle und Grenzfälle', 'Speichere das benannte Artefakt oder den Prüfstand'] },
      'lab-12': { title: 'Eine Aufgabe über A2A delegieren', summary: 'Endpunkt, Authentifizierung, Kontextkennungen, Zeitlimits und serverseitige Nachverfolgbarkeit konfigurieren.', artifacts: ['A2A-Anfrage mit Rückantwort', 'Absicherungscheckliste'], concepts: ['A2A', 'Vertrauensgrenze'], checklist: ['Lies die Lab-Beschreibung: Eine Aufgabe über A2A delegieren', 'Führe den Konfigurations- oder Entwurfsschritt durch', 'Prüfe Erfolgsfälle und Grenzfälle', 'Speichere das benannte Artefakt oder den Prüfstand'] },
