      'lab-15': { title: 'Einen repräsentativen Agententestsatz erstellen', summary: 'Kern-, Robustheits-, Architektur- und Grenzfälle mit beobachtbaren Kriterien erstellen.', artifacts: ['Versionierter Testsatz'], concepts: ['Testsatz', 'Auswertung'], checklist: ['Lies die Lab-Beschreibung: Einen repräsentativen Agententestsatz erstellen', 'Führe den Konfigurations- oder Entwurfsschritt durch', 'Prüfe Erfolgsfälle und Grenzfälle', 'Speichere das benannte Artefakt oder den Prüfstand'] },
      'lab-16': { title: 'Auswertungen durchführen und Agentenfehler einordnen', summary: 'Mit einem Ausgangsstand vergleichen, Fehler klassifizieren, Belege prüfen und eine Änderung auf Regressionen testen.', artifacts: ['Fehleranalysetabelle', 'Vorher-Nachher-Nachweise'], concepts: ['Auswertung', 'Fehlerpriorisierung'], checklist: ['Lies die Lab-Beschreibung: Auswertungen durchführen und Agentenfehler einordnen', 'Führe den Konfigurations- oder Entwurfsschritt durch', 'Prüfe Erfolgsfälle und Grenzfälle', 'Speichere das benannte Artefakt oder den Prüfstand'] },
