      'lab-18': { title: 'Environment Variables und Connection References konfigurieren', summary: 'Fest hinterlegte Werte entfernen sowie Zielumgebungskonfiguration und Wiederherstellungsimport überprüfen.', artifacts: ['Grundlegende Funktionstests', 'Freigabekandidat'], concepts: ['Environment Variables', 'Connection References'], checklist: ['Lies die Lab-Beschreibung: Environment Variables und Connection References konfigurieren', 'Führe den Konfigurations- oder Entwurfsschritt durch', 'Prüfe Erfolgsfälle und Grenzfälle', 'Speichere das benannte Artefakt oder den Prüfstand'] },
      'lab-19': { title: 'Über eine Power Platform Pipeline bereitstellen', summary: 'Phasen, Rollen, Versionsunterschiede, verwaltete Bereitstellung und grundlegende Funktionstests prüfen.', artifacts: ['Bereitstellungsnachweise', 'Freigabe- oder Stoppentscheidung'], concepts: ['Pipelines', 'Veröffentlichung'], checklist: ['Lies die Lab-Beschreibung: Über eine Power Platform Pipeline bereitstellen', 'Führe den Konfigurations- oder Entwurfsschritt durch', 'Prüfe Erfolgsfälle und Grenzfälle', 'Speichere das benannte Artefakt oder den Prüfstand'] },
      'lab-20': { title: 'Überwachung und Wiederherstellung einer Veröffentlichung proben', summary: 'Eine Veröffentlichung durchführen, einen simulierten 5xx-Vorfall einordnen, eindämmen und die Wiederherstellung proben.', artifacts: ['Betriebshandbuch', 'Vorfallszeitleiste', 'Regressionstestfall'], concepts: ['Betrieb', 'Wiederherstellung'], checklist: ['Lies die Lab-Beschreibung: Überwachung und Wiederherstellung einer Veröffentlichung proben', 'Führe den Konfigurations- oder Entwurfsschritt durch', 'Prüfe Erfolgsfälle und Grenzfälle', 'Speichere das benannte Artefakt oder den Prüfstand'] },
