Object.assign(localeData.de.questions, {
  46: { question: 'Welcher Entwurf passt am besten zu einem Prozess, der mehrere Fragen stellt, bevor er eine Aufgabe abschließt?', options: ['Eine Antwort in einer einzigen Gesprächsrunde.', 'Ein Thema mit mehreren Gesprächsrunden, Verzweigungen und Variablen.', 'Ausschließlich eine öffentliche Website als Wissensquelle.', 'Ein Telemetrieereignis.'], explanation: 'Mehrstufige Gespräche sind geeignet, wenn der Agent vor einer Aktion mehrere Eingaben erfassen und validieren muss.' },
  47: { question: 'Was ist der Hauptzweck gut entworfener Auslöserformulierungen?', options: ['Geheimnisse speichern.', 'Die Erkennung und Zuordnung der Benutzerabsicht verbessern.', 'Die Konnektorauthentifizierung ersetzen.', 'Pipeline-Ziele konfigurieren.'], explanation: 'Auslöserformulierungen helfen dem Agenten, das von einem Thema behandelte Szenario zu erkennen.' },
  48: { question: 'Wann sollte ein Team mehrere spezialisierte Agenten in Betracht ziehen?', options: ['Für jede noch so kleine Aufgabe.', 'Wenn sich Fachgebiete, Verantwortlichkeiten, Berechtigungen oder spezialisiertes Schlussfolgern wesentlich unterscheiden.', 'Nur wenn keine Themen vorhanden sind.', 'Immer wenn ein Flow fehlschlägt.'], explanation: 'Microsoft empfiehlt Delegation für klar getrennte Fachgebiete, warnt jedoch vor unnötiger Ausweitung der Architektur.' },
  49: { question: 'Was sollte beim Verschieben einer Lösung zwischen Umgebungen vom Agenten getrennt werden?', options: ['Jede Gesprächsnachricht.', 'Umgebungsspezifische Endpunkte und Verbindungen.', 'Nur der Agentenname.', 'Sämtliche Thementexte.'], explanation: 'Environment Variables und Connection References lagern umgebungsspezifische Konfiguration aus.' },
  50: { question: 'Welche Quelle ist am besten geeignet, wenn Unternehmensdaten die Berechtigungen auf Quellenebene beachten müssen?', options: ['Eine kopierte globale Variable.', 'Ein Copilot connector mit den erforderlichen Unternehmensberechtigungen.', 'Eine öffentliche Website.', 'Eine anonyme Azure AI Search-Verbindung.'], explanation: 'Copilot connectors sind darauf ausgelegt, für autorisierte Benutzer die Berechtigungen auf Quellenebene einzuhalten.' },
  51: { question: 'Was sollte überprüft werden, wenn ein Agent technisch funktioniert, Benutzer aber schlechte Antworten erhalten?', options: ['Nur das Logo.', 'Analysen, Gesprächsprotokolle, Quellenbindung und die schrittweise Verbesserung des Themenentwurfs.', 'Nur der Browsercache.', 'Der Name des GitHub-Repositorys.'], explanation: 'Microsoft-Schulungen betonen Analysen und Gesprächsprotokolle als Rückmeldung für die schrittweise Verbesserung.' },
  52: { question: 'Welche Rolle hat eine Adaptive Card in einem Copilot Studio-Gespräch?', options: ['Eine Bereitstellungspipeline.', 'Eine strukturierte, interaktive Darstellung von Daten und Aktionen.', 'Ein Ersatz für Entra ID.', 'Ein Vektorindex.'], explanation: 'Adaptive Cards stellen strukturierte Informationen dar und können in unterstützten Kanälen Benutzeraktionen erfassen.' },
  53: { question: 'Welche Integration ist geeignet, wenn eine dokumentierte REST-API über mehrere Themen hinweg wiederverwendbar sein soll?', options: ['Rohe HTTP-Anfragen duplizieren.', 'Ein benutzerdefinierter Konnektor mit definiertem API-Vertrag und Authentifizierung.', 'Ein Gesprächsprotokoll auf Themenebene.', 'Eine System Fallback-Nachricht.'], explanation: 'Ein benutzerdefinierter Konnektor zentralisiert den API-Vertrag und die Authentifizierungskonfiguration.' },
  54: { question: 'Was sagt der offizielle AB-620-Prüfungsleitfaden über Vorschaufunktionen?', options: ['Sie sind immer ausgeschlossen.', 'Häufig verwendete Vorschaufunktionen können vorkommen, obwohl die meisten Fragen allgemein verfügbare Funktionen betreffen.', 'Es werden ausschließlich Vorschaufunktionen geprüft.', 'Für jede Vorschaufunktion wird identisches Verhalten garantiert.'], explanation: 'Der Leitfaden stellt ausdrücklich fest, dass sich die meisten Fragen auf allgemein verfügbare Funktionen beziehen, häufig genutzte Vorschaufunktionen aber ebenfalls vorkommen können.' },
  55: { question: 'Welche Integration sollte bevorzugt werden, wenn bereits ein unterstützter Konnektor für das Zielgeschäftssystem existiert?', options: ['Eine benutzerdefinierte REST-API', 'Ein integrierter Konnektor', 'Ein MCP-Server', 'Eine direkte Datenbankabfrage'], explanation: 'Microsoft empfiehlt die einfachste unterstützte Integration. Verwende eine benutzerdefinierte API nur, wenn der vorhandene Konnektor die Anforderung nicht erfüllt.' },
  56: { question: 'Ein Flow muss nacheinander eine Genehmigung erstellen, zwei Systeme aktualisieren und eine Führungskraft benachrichtigen. Welche Funktion passt am besten?', options: ['Azure AI Search', 'Power Automate oder ein Agentenflow', 'Eine Auslöserformulierung', 'Eine statische Adaptive Card'], explanation: 'Die Orchestrierung mehrstufiger Geschäftsabläufe gehört in einen Flow, während das Thema die Gesprächseingaben erfasst.' },
  57: { question: 'Welche ZWEI Vorgehensweisen verbessern die Identitätsstrategie eines Unternehmens?', options: ['Berechtigungen nach dem Prinzip der geringsten Rechte vergeben.', 'Ein Administratorkonto für alle Agenten gemeinsam nutzen.', 'Bei benutzergesteuerten Zugriffen gegebenenfalls delegierte Berechtigungen verwenden.', 'API-Schlüssel fest in Themen hinterlegen.'], explanation: 'Das Prinzip der geringsten Rechte begrenzt den Schadensumfang. Delegierter Zugriff kann bei benutzergesteuerten Vorgängen den Kontext des angemeldeten Benutzers erhalten.' },
  58: { question: 'Welcher Bereitstellungsentwurf unterstützt sichere Produktionsfreigaben am besten?', options: ['Direkt in der Produktion entwickeln.', 'Getrennte Entwicklungs-, Test- und Produktionsumgebungen mit ALM verwenden.', 'Jedem Benutzer die Bearbeitung des Produktionsagenten erlauben.', 'Jeden Entwurf sofort veröffentlichen.'], explanation: 'Getrennte Umgebungen und ein ALM-Prozess ermöglichen Tests und Freigaben vor der Bereitstellung in der Produktion.' },
  59: { question: 'Welche ZWEI Kontrollen gehören zu einer Strategie für verantwortungsvolle KI bei einem Genehmigungsagenten mit weitreichenden Auswirkungen?', options: ['Menschliche Prüfung bei Entscheidungen mit weitreichenden Auswirkungen.', 'Uneingeschränkte autonome Ausführung.', 'Quellenbindung an vertrauenswürdige Daten.', 'Überwachungsprotokolle deaktivieren.'], explanation: 'Menschliche Aufsicht und vertrauenswürdige Quellenbindung reduzieren Risiken in sensiblen Szenarien. Verantwortungsvolle KI betrifft den gesamten Lebenszyklus und ist kein einzelner Schalter.' },
  60: { question: 'Ordne jeder Komponente ihren Hauptzweck zu.', options: ['1. Konnektorwerkzeug', '2. REST-API-Werkzeug', '3. MCP', '4. A2A'], matchLabels: ['A. Vorgefertigte Anwendungsintegration', 'B. Benutzerdefinierte HTTP-Integration', 'C. Interoperabilität externer Werkzeuge', 'D. Zusammenarbeit zwischen Agenten'], explanation: 'Die Komponenten stehen für vorgefertigte Integration, benutzerdefinierte HTTP-Integration, Interoperabilität externer Werkzeuge und Kommunikation zwischen Agenten.' },
  61: { question: 'Was sollte ein Agentenflow im Produktionsbetrieb tun, wenn ein Konnektor eine vorübergehende Zeitüberschreitung meldet?', options: ['Den rohen HTTP-Fehler anzeigen.', 'Gegebenenfalls erneut versuchen, den Fehler protokollieren und eine verständliche Ausweichantwort zurückgeben.', 'Den Fehler ignorieren.', 'Den Konnektor löschen.'], explanation: 'Der Flow sollte vorübergehende von dauerhaften Fehlern unterscheiden und eine kontrollierte Antwort für Benutzer bereitstellen.' },
  62: { question: 'Welche ZWEI Werte sind typische Flow-Ausgaben, die an den Agenten zurückgegeben werden?', options: ['Eine Ticketnummer.', 'Ein verborgenes API-Kennwort.', 'Ein Bestellstatus.', 'Ein Bereitstellungsgeheimnis.'], explanation: 'Ausgaben sollten nützliche Geschäftsergebnisse enthalten. Geheimnisse dürfen nicht in das Gespräch zurückgegeben werden.' },
  63: { question: 'Ein Flow ist mit einem Thema verknüpft und muss sofort ein Ergebnis zurückgeben. Welche Konfiguration ist erforderlich?', options: ['Eine aktivierte asynchrone Antwort.', 'Eine synchrone Antwortaktion wie Respond to the agent.', 'Keine Ausgabeparameter.', 'Ein zweiter, unabhängiger Auslöser.'], explanation: 'Laut Microsoft müssen von Agenten aufgerufene Flows ihre Werte synchron zurückgeben, damit der Agent sie zuverlässig verwenden kann.' },
  64: { question: 'Welche Darstellung eignet sich am besten, um mehrere strukturierte Felder und eine Entscheidung eines Benutzers zu erfassen?', options: ['Eine Adaptive Card mit Eingabefeldern und einer Absendeaktion.', 'Eine Wissensquelle.', 'Ein Azure AI Search-Index.', 'Eine verborgene globale Variable.'], explanation: 'Adaptive Cards eignen sich für strukturierte interaktive Eingaben. Verwende eindeutige Absendedaten, wenn mehrere Karten gleichzeitig aktiv sein können.' },
  65: { question: 'Welche Aussage über Hosts für Adaptive Cards ist richtig?', options: ['Jeder Host unterstützt dieselbe Schemaversion und dieselben Aktionen.', 'Das unterstützte Schema und die Aktionen hängen vom Zielhost ab.', 'Adaptive Cards können nur Text enthalten.', 'Adaptive Cards ersetzen die Authentifizierung.'], explanation: 'Microsoft dokumentiert hostspezifische Schemabeschränkungen, unter anderem Unterschiede zwischen Web Chat, Teams und Omnichannel.' },
  66: { question: 'Was sollte zuerst untersucht werden, wenn ein Agent nach der Aktualisierung von Dokumenten weiterhin veraltete Verfahren zurückgibt?', options: ['Das Begrüßungsthema.', 'Die Synchronisierung und Indizierung der Wissensquelle.', 'Das Logo.', 'Die Anzahl der Variablen.'], explanation: 'Veraltete Abrufinhalte deuten häufig auf mangelnde Quellenaktualität, Indizierung oder Synchronisierung hin und nicht auf die Gesprächsgestaltung.' },
  67: { question: 'Welche Quelle ist grundsätzlich für große Dokumentensammlungen eines Unternehmens mit semantischem Informationsabruf geeignet?', options: ['Azure AI Search als konfigurierte Wissensquelle.', 'Eine globale Variable mit sämtlichen Dokumenten.', 'Ein Begrüßungsthema.', 'Eine einzelne Adaptive Card.'], explanation: 'Azure AI Search ist eine unterstützte Wissensquelle für große Dokumentensammlungen und RAG-Szenarien.' },
  68: { question: 'Welche ZWEI Bedingungen sprechen deutlich dafür, Funktionen auf verbundene Agenten aufzuteilen?', options: ['Verschiedene Teams benötigen unabhängige Bereitstellung und Zuständigkeit.', 'Jeder noch so kleine Vorgang verdient einen eigenen Agenten.', 'Verschiedene Fachgebiete benötigen unterschiedliche Berechtigungen oder unterschiedliches Wissen.', 'Der Hauptagent besitzt nur ein einfaches Werkzeug.'], explanation: 'Unabhängige Zuständigkeiten sowie bedeutsame Fachgebiets- oder Sicherheitsgrenzen rechtfertigen verbundene Agenten. Die Aufteilung jeder Kleinigkeit erzeugt unnötigen Orchestrierungsaufwand.' },
  69: { question: 'Welcher wesentliche Zielkonflikt entsteht bei Architekturen mit verbundenen Agenten?', options: ['Sie machen sämtliche Tests überflüssig.', 'Sie können die Latenz erhöhen und den Governance-Aufwand vergrößern.', 'Sie können keine Werkzeuge verwenden.', 'Sie entfernen immer den Gesprächskontext.'], explanation: 'Microsoft weist auf zusätzliche Orchestrierungsschritte und weitere Verantwortlichkeiten für Tests und Governance hin.' },
  70: { question: 'Welche Aussage unterscheidet MCP und A2A korrekt?', options: ['MCP dient der Kommunikation zwischen Agenten und A2A der Dokumentensuche.', 'MCP standardisiert die Werkzeug- und Dienstintegration, A2A die Kommunikation zwischen Agenten.', 'Es sind austauschbare Namen für dasselbe Protokoll.', 'Keines der beiden unterstützt Authentifizierung.'], explanation: 'Diese Unterscheidung ist wichtig, da einige inoffizielle Übungsfragen MCP und A2A fälschlich als austauschbar behandeln.' },
  71: { question: 'Welchen MCP-Transport unterstützt Copilot Studio derzeit laut Microsoft-Dokumentation?', options: ['Ausschließlich SSE.', 'Streamable-Transport.', 'FTP.', 'Ausschließlich WebSocket.'], explanation: 'Microsoft dokumentiert die Unterstützung von Streamable-Transport und weist darauf hin, dass SSE nach August 2025 nicht mehr unterstützt wird.' },
  72: { question: 'Welche ZWEI Prüfungen sind vor der Verbindung mit einem externen A2A-Agenten angebracht?', options: ['Seinen Umgang mit Daten und seine Berechtigungen überprüfen.', 'Auf Tests verzichten, weil das Protokoll standardisiert ist.', 'Sicherstellen, dass Beobachtbarkeit und Nachverfolgbarkeit vorhanden sind.', 'Sämtliche Geheimnisse mit dem externen Agenten teilen.'], explanation: 'Externe Agentenverbindungen erfordern die Prüfung von Datenflüssen, Qualität, Sicherheit, Berechtigungen, Beobachtbarkeit und menschlicher Aufsicht.' },
  73: { question: 'Was ist der wichtigste Nutzen eines Copilot Studio-Testsatzes?', options: ['Er ersetzt die Produktionsüberwachung.', 'Er ermöglicht wiederholbare Auswertungen mit vorgegebenen Eingaben und erwarteten Ergebnissen.', 'Er veröffentlicht einen Agenten automatisch.', 'Er erstellt einen MCP-Server.'], explanation: 'Testsätze unterstützen wiederholbare Auswertungen und helfen beim Vergleich von Qualitätsmetriken wie Quellenbindung und Absichtserkennung.' },
  74: { question: 'Welche Kombination von Metriken ist besonders hilfreich, um ein Problem mit der Quellenbindung zu erkennen?', options: ['Hohe Quellenbindung und geringe Relevanz.', 'Hohe Absichtserkennung und geringe Quellenbindung.', 'Ausschließlich geringe Absichtserkennung und hohe Quellenbindung.', 'Anzahl der Themen und Karten.'], explanation: 'Der Agent kann die Anfrage verstehen und dennoch anhand unbelegten oder externen Wissens antworten.' },
  75: { question: 'Welche ALM-Komponente speichert umgebungsspezifische Endpunkte, ohne die Agentenlogik zu ändern?', options: ['Eine Environment Variable.', 'Eine Auslöserformulierung eines Themas.', 'Eine Adaptive Card.', 'Ein Gesprächsprotokoll.'], explanation: 'Environment Variables lagern Werte aus, die sich zwischen Entwicklung, Test und Produktion unterscheiden.' },
  76: { question: 'Welche ALM-Komponente trennt eine Lösung von der tatsächlichen Verbindung in der Umgebung?', options: ['Eine Connection Reference.', 'Eine globale Gesprächsvariable.', 'Eine Prompt-Vorlage.', 'Ein Suchindex.'], explanation: 'Connection References ermöglichen es, dieselbe Lösung mit unterschiedlichen Verbindungen der Zielumgebung zu verknüpfen.' },
  77: { question: 'Für welche Zielgruppe sind Teams, Entra ID-Authentifizierung und Unternehmensberechtigungen üblicherweise besonders geeignet?', options: ['Interne Mitarbeitende.', 'Anonyme Besucher einer öffentlichen Website.', 'Eine öffentliche Marketingzielgruppe.', 'Ein Suchcrawler.'], explanation: 'Die Zielgruppenplanung beeinflusst Kanal, Identität, Wissen, Governance und Skalierung. Interne Mitarbeiteragenten verwenden häufig Teams und die Organisationsidentität.' },
  78: { question: 'Welche Antwort ist das beste Beispiel für eine schreibgeschützte Unternehmensintegration?', options: ['Den aktuellen Bestellstatus abrufen.', 'Eine Bestellung genehmigen.', 'Einen Kundendatensatz löschen.', 'Eine Zahlung auslösen.'], explanation: 'Eine schreibgeschützte Integration ruft Informationen ab, ohne das externe System zu ändern. Schreibende und hybride Integrationen benötigen stärkere Kontrollen.' },
  79: { question: 'Ein Agent ruft einen Flow auf und muss dessen Ergebnis noch in derselben Gesprächsrunde verwenden können. Welches Antwortverhalten ist erforderlich?', options: ['Eine aktivierte asynchrone Antwort.', 'Eine synchrone Antwort über Respond to the agent.', 'Keine Antwortaktion.', 'Ein zeitgesteuerter Auslöser.'], explanation: 'Laut Microsoft sollten von Agenten verwendete Flows ihre Werte synchron zurückgeben. Eine Ausführung im Hintergrund kann einen unerwarteten Fehler verursachen.' },
  80: { question: 'Welche ZWEI Eigenschaften gehören in einen zuverlässigen Flow-Vertrag?', options: ['Typisierte Definitionen für Eingaben und Ausgaben.', 'Undokumentierte Seiteneffekte.', 'Ausdrückliche Fehlerzustände.', 'Ein fest hinterlegter Produktionsendpunkt.'], explanation: 'Ein klarer Vertrag macht Eingaben, Ausgaben und Fehlerverhalten beobachtbar und wiederverwendbar. Umgebungsspezifische Werte gehören in die Konfiguration.' },
  81: { question: 'Ein Abrufstest liefert relevante Dokumente, die jedoch mehrere Monate alt sind. Welche Dimension sollte zuerst untersucht werden?', options: ['Quellenaktualität und Indexsynchronisierung.', 'Das Begrüßungsthema.', 'Der Rahmen der Adaptive Card.', 'Die Anzahl der Auslöserformulierungen.'], explanation: 'Die Abrufqualität hängt von aktuellen indizierten Inhalten ab. Ein relevantes Ergebnis reicht nicht aus, wenn die Quelle veraltet ist.' },
  82: { question: 'Welchen Belegzustand sollte ein quellengebundener Agent zurückgeben, wenn sich Quellen wesentlich widersprechen?', options: ['complete', 'insufficientEvidence', 'conflict', 'success'], explanation: 'Der Zustand conflict ist sicherer, als stillschweigend eine von mehreren widersprüchlichen Quellen auszuwählen. Flow oder Prompt sollten die Mehrdeutigkeit für die weitere Verarbeitung sichtbar machen.' },
  83: { question: 'Warum sollten ein übergeordneter und ein verbundener Agent gemeinsame Korrelationskennungen verwenden?', options: ['Damit der untergeordnete Agent anonym bleibt.', 'Um delegierte Arbeit über Ablaufspuren hinweg zuzuordnen und die vollständige Anfrage bei Fehlern zu untersuchen.', 'Um die Authentifizierung zu umgehen.', 'Um die Agentenbeschreibung zu ersetzen.'], explanation: 'Korrelations-IDs verbinden übergeordnete und delegierte Aktivitäten, sodass Betriebsteams eine Anfrage über getrennte Agentenablaufspuren hinweg verfolgen können.' },
  84: { question: 'Welche ZWEI Risiken müssen vor der Verbindung mit einem externen A2A-Agenten geprüft werden?', options: ['Datenweitergabe und Berechtigungsgrenzen.', 'Ob der Agent ein dekoratives Logo hat.', 'Verhalten bei Zeitüberschreitungen und Zuverlässigkeit.', 'Ob alle internen Geheimnisse weitergeleitet werden.'], explanation: 'Externe Agentenverbindungen führen eine Vertrauensgrenze ein. Prüfe Datenverarbeitung, Berechtigungen, Beobachtbarkeit, Zuverlässigkeit und menschliche Aufsicht.' },
  85: { question: 'Ein schreibgeschützter MCP-Server stellt Werkzeuge und Ressourcen bereit. Was sollte vor seiner Aktivierung für einen Agenten getan werden?', options: ['Jeden erkannten Vorgang aktivieren.', 'Authentifizierung, Werkzeugumfang, Datenzugriff und DLP-Richtlinie prüfen.', 'Ihn durch ein Begrüßungsthema ersetzen.', 'Seine Zugangsdaten in einer globalen Variablen speichern.'], explanation: 'Die MCP-Erkennung hebt Governance-Anforderungen nicht auf. Prüfe vor der Nutzung den Server, die Authentifizierung, die verfügbaren Vorgänge und die Datenrichtlinie.' },
  86: { question: 'Eine Computer Use-Aufgabe könnte Datensätze löschen, wenn der Oberflächenzustand falsch erkannt wird. Welche Kontrolle ist am besten geeignet?', options: ['Sie in einer isolierten Umgebung mit ausdrücklichen Abbruch- und Bestätigungsregeln ausführen.', 'Ihr globale Administratorberechtigungen erteilen.', 'Sämtliche menschlichen Prüfungen entfernen.', 'Öffentliches Internetwissen verwenden.'], explanation: 'Computer Use arbeitet probabilistisch und kann unbeabsichtigte Aktionen ausführen. Isolation, geringstmögliche Rechte, Zulassungslisten und menschliche Bestätigung reduzieren das Risiko.' },
  87: { question: 'Welche Testsatzkategorie prüft, ob ein Agent Anfragen außerhalb seines Zuständigkeitsbereichs ablehnt oder sicher behandelt?', options: ['Kernfälle', 'Robustheitsfälle', 'Architekturfälle', 'Grenzfälle'], explanation: 'Grenzfälle prüfen Zuständigkeitsgrenzen, Antwortverzicht, Berechtigungsgrenzen sowie unsichere oder nicht unterstützte Anfragen.' },
  88: { question: 'Eine Auswertung zeigt nach einer Prompt-Änderung eine Regression. Was sollte vor der Veröffentlichung geschehen?', options: ['Sofort veröffentlichen, weil sich eine Metrik verbessert hat.', 'Vorher-Nachher-Belege vergleichen und die betroffenen Regressionstests ausführen.', 'Den Ausgangsstand löschen.', 'Die Überwachung deaktivieren.'], explanation: 'Eine Qualitätsverbesserung ist nicht sicher, wenn sie Kernverhalten beeinträchtigt. Vergleiche die Belege und führe repräsentative Regressionstests erneut aus.' },
  89: { question: 'Welches Bereitstellungsartefakt sollte umgebungsspezifische Endpunkte enthalten, ohne den Agentenentwurfsbereich zu ändern?', options: ['Eine fest hinterlegte URL.', 'Eine Environment Variable.', 'Ein Gesprächsprotokoll.', 'Eine Auslöserformulierung.'], explanation: 'Environment Variables trennen Konfiguration von der Lösungslogik und unterstützen das Verschieben zwischen Umgebungen.' },
  90: { question: 'Bei einer Produktionsveröffentlichung schlägt ein grundlegender Funktionstest fehl, und eine nachgelagerte API hat bereits einen Schreibvorgang erhalten. Was ist der sicherste nächste Schritt?', options: ['Die Veröffentlichung fortsetzen und den Fehler verbergen.', 'Die Veröffentlichung anhalten oder eindämmen, den Vorfall dokumentieren und dem Wiederherstellungshandbuch folgen.', 'Sämtliche Telemetrie löschen.', 'Unbegrenzt erneut versuchen.'], explanation: 'Eine Freigabeprüfung sollte den weiteren Rollout stoppen, wenn die Nachweise nicht ausreichen. Externe Seiteneffekte können Ausgleichsaktionen statt eines einfachen Paket-Rollbacks erfordern.' },
});
